#!/usr/bin/env python3
from __future__ import annotations

import argparse
import json
import re
import sys
from pathlib import Path


CLASS_NAME_RE = re.compile(r"^[A-Z][A-Za-z0-9]*$")


def render_policy(class_name: str, design_status_bar_detected: bool) -> str:
    mode = "overlay" if design_status_bar_detected else "hidden"
    value = "true" if design_status_bar_detected else "false"
    return (
        "// GENERATED by iFF make_status_bar_policy.py; DO NOT EDIT.\n"
        f"abstract final class {class_name} {{\n"
        f"  static const bool designStatusBarDetected = {value};\n"
        f"  static const String mode = '{mode}';\n"
        f"  static const bool transparent = {value};\n"
        f"  static const bool overlaysContent = {value};\n"
        "  static const bool reserveTopInset = false;\n"
        "}\n"
    )


def main() -> int:
    parser = argparse.ArgumentParser(description="Generate a typed Dart status-bar policy from one iFF scene")
    parser.add_argument("--scene", required=True)
    parser.add_argument("--class-name", required=True)
    parser.add_argument("--out", required=True)
    args = parser.parse_args()

    scene_path = Path(args.scene).resolve()
    out = Path(args.out).resolve()
    if not scene_path.is_file():
        print(f"ERROR: scene not found: {scene_path}", file=sys.stderr)
        return 2
    if CLASS_NAME_RE.fullmatch(args.class_name) is None:
        print(f"ERROR: invalid Dart class name: {args.class_name}", file=sys.stderr)
        return 2
    try:
        scene = json.loads(scene_path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as error:
        print(f"ERROR: invalid scene JSON: {error}", file=sys.stderr)
        return 2
    if not isinstance(scene, dict):
        print("ERROR: scene root must be an object", file=sys.stderr)
        return 2
    exclusions = scene.get("systemUiExclusions") or []
    if not isinstance(exclusions, list):
        print("ERROR: scene.systemUiExclusions must be a list", file=sys.stderr)
        return 2
    design_status_bar_detected = any(
        isinstance(item, dict) and item.get("role") == "status_bar"
        for item in exclusions
    )

    out.parent.mkdir(parents=True, exist_ok=True)
    temporary = out.with_name(f".{out.name}.tmp")
    temporary.write_text(render_policy(args.class_name, design_status_bar_detected), encoding="utf-8")
    temporary.replace(out)
    print(f"OK: generated {out} ({'overlay' if design_status_bar_detected else 'hidden'})")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
